import "server-only";

import { and, eq } from "drizzle-orm";
import { alias } from "drizzle-orm/pg-core";

import { db, explanations, posts, termExamples, terms } from "@/db";

import { generateExamples, translateExamples } from "./examples";

export type ExamplesResult =
  { ok: true; sentences: string[] } | { ok: false; reason: "missing" | "no-examples" };

const english = alias(termExamples, "examples_en");

/**
 * The 5 English usage examples of one term (13.2, D-09): served from the
 * database when they exist (every post made since 13.2 has them), otherwise
 * generated by one Claude call and stored. That is the case of a post
 * published before 13.2, the first time the examples view of one of its words
 * is opened. Only terms of published posts have examples.
 *
 * Two requests at the same time can't store two versions: the UNIQUE
 * (term_id, language) constraint keeps the first one, and both answers read
 * back what is stored.
 */
export async function getOrCreateExamples(termId: string): Promise<ExamplesResult> {
  const [row] = await db
    .select({
      postId: terms.postId,
      headword: terms.headword,
      surface: terms.surface,
      text: posts.text,
      definition: explanations.definition,
      sentences: english.sentences,
    })
    .from(terms)
    .innerJoin(posts, and(eq(posts.id, terms.postId), eq(posts.status, "published")))
    .leftJoin(explanations, and(eq(explanations.termId, terms.id), eq(explanations.language, "en")))
    .leftJoin(english, and(eq(english.termId, terms.id), eq(english.language, "en")))
    .where(eq(terms.id, termId));

  if (!row) return { ok: false, reason: "missing" };
  if (row.sentences) return { ok: true, sentences: row.sentences };

  const { output, model } = await generateExamples({
    postId: row.postId,
    headword: row.headword,
    surface: row.surface,
    text: row.text ?? "",
    definition: row.definition,
  });
  await db
    .insert(termExamples)
    .values({ termId, language: "en", sentences: output, model })
    .onConflictDoNothing({ target: [termExamples.termId, termExamples.language] });

  return readStored(termId, "en");
}

/**
 * The French translation of a term's 5 examples (13.2, the examples view's own
 * Translate): served from the database when it exists, otherwise generated by
 * one Claude call and stored, once. The English examples must exist.
 */
export async function getOrCreateExamplesFrench(termId: string): Promise<ExamplesResult> {
  const [row] = await db
    .select({ postId: terms.postId, headword: terms.headword })
    .from(terms)
    .innerJoin(posts, and(eq(posts.id, terms.postId), eq(posts.status, "published")))
    .where(eq(terms.id, termId));
  if (!row) return { ok: false, reason: "missing" };

  const french = await readStored(termId, "fr");
  if (french.ok) return french;

  const en = await readStored(termId, "en");
  if (!en.ok) return en;

  const { output, model } = await translateExamples({
    postId: row.postId,
    headword: row.headword,
    sentences: en.sentences,
  });
  await db
    .insert(termExamples)
    .values({ termId, language: "fr", sentences: output, model })
    .onConflictDoNothing({ target: [termExamples.termId, termExamples.language] });

  return readStored(termId, "fr");
}

/** What is stored now: ours, or what a parallel request stored first. */
async function readStored(termId: string, language: "en" | "fr"): Promise<ExamplesResult> {
  const [stored] = await db
    .select({ sentences: termExamples.sentences })
    .from(termExamples)
    .where(and(eq(termExamples.termId, termId), eq(termExamples.language, language)));
  return stored ? { ok: true, sentences: stored.sentences } : { ok: false, reason: "no-examples" };
}
